//! Lookup tables: test names, fuel/air status strings, compliance
//! levels, fuel types and Mode 06 test IDs.
//!
//! The DTC table (2066 entries) is generated by `tools/specs-generator` into
//! `dtc_table.rs`; everything here is small and hand-ported.
//!
// SPDX-License-Identifier: GPL-3.0-or-later

/// Ignition type names, indexed by bit 12 of the Mode 01 PID 01 reply.
pub const IGNITION_TYPE: [&str; 2] = ["spark", "compression"];

/// The 3 base diagnostic tests always present in a PID 01 reply.
pub const BASE_TESTS: [&str; 3] = [
    "MISFIRE_MONITORING",
    "FUEL_SYSTEM_MONITORING",
    "COMPONENT_MONITORING",
];

/// Spark-ignition tests (byte 2 of the PID 01 reply).
///
/// `None` marks reserved bit positions, mirroring `SPARK_TESTS`.
pub const SPARK_TESTS: [Option<&str>; 8] = [
    Some("CATALYST_MONITORING"),
    Some("HEATED_CATALYST_MONITORING"),
    Some("EVAPORATIVE_SYSTEM_MONITORING"),
    Some("SECONDARY_AIR_SYSTEM_MONITORING"),
    None,
    Some("OXYGEN_SENSOR_MONITORING"),
    Some("OXYGEN_SENSOR_HEATER_MONITORING"),
    Some("EGR_VVT_SYSTEM_MONITORING"),
];

/// Compression-ignition tests (byte 2 of the PID 01 reply).
pub const COMPRESSION_TESTS: [Option<&str>; 8] = [
    Some("NMHC_CATALYST_MONITORING"),
    Some("NOX_SCR_AFTERTREATMENT_MONITORING"),
    None,
    Some("BOOST_PRESSURE_MONITORING"),
    None,
    Some("EXHAUST_GAS_SENSOR_MONITORING"),
    Some("PM_FILTER_MONITORING"),
    Some("EGR_VVT_SYSTEM_MONITORING"),
];

